use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut result = Vec::new();
    let mut left = input.as_array().unwrap();
    let mut right = input.as_array().unwrap();
    left.sort_by_key(|k| k.as_i64().unwrap());
    right.sort_by_key(|k| k.as_i64().unwrap());
    let mut i = 0;
    let mut j = 0;
    while i < left.len() && j < right.len() {
        let key = left[i].as_i64().unwrap();
        let left_value = left[i].clone();
        while j < right.len() && right[j].as_i64().unwrap() < key {
            j += 1;
        }
        if j < right.len() && right[j].as_i64().unwrap() == key {
            result.push(vec![key, left_value, right[j].clone()]);
            j += 1;
        }
        i += 1;
    }
    result.into()
}
